import React, { useEffect, useState } from 'react'
import useLayerStore from '../../../utils/store'
import { getAssetMeta } from '../../../utils/dataV2.js'
import colors from '../../../utils/colors'
import DarkBorder from '../../border-container/dark-border-container'
import {
  EyesContainer,
  PreviewContainer,
  TextContainer,
  LeftArrow,
  RightArrow,
  ColorPreview,
  ButtonContainer,
  InnerContainer,
} from './eyes.style'

const Eyes = () => {
  const addAssetLayer = useLayerStore((state) => state.addAssetLayer)
  const setSelectedLayer = useLayerStore((state) => state.setSelectedLayer)
  const setColor = useLayerStore((state) => state.setColor)
  const layerArr = useLayerStore((state) => state.layerArr)
  const updateLayer = useLayerStore((state) => state.updateLayer)
  const [hex, setHex] = useState('#393939')
  const eyeColorOptions =
    getAssetMeta('Physique', 'Etc_-_Eye_Color')?.layers?.[0]?.colorOptions || []

  const addEyeLayer = () => {
    const eyeLayerIndex = addAssetLayer('Physique', 'Etc_-_Eye_Color', false)
    if (eyeLayerIndex !== null) {
      setSelectedLayer(eyeLayerIndex)
      setColor('primary_Black.png')
    }
  }

  const incrementEyeColor = () => {
    const eyeIndex = layerArr.findIndex(
      (layer) => layer.assetName === 'Etc_-_Eye_Color'
    )
    if (eyeIndex > -1) {
      const currentLayer = {
        ...layerArr[eyeIndex],
        parts: layerArr[eyeIndex].parts.map((part) => ({ ...part })),
      }
      const currentSelection = currentLayer.parts?.[0]?.selection
      const currentColorIndex = eyeColorOptions.findIndex(
        (color) => color === currentSelection
      )
      const nextSelection =
        currentColorIndex < eyeColorOptions.length - 1
          ? eyeColorOptions[currentColorIndex + 1]
          : eyeColorOptions[0]
      currentLayer.parts = currentLayer.parts.map((part, index) =>
        index === 0 ? { ...part, selection: nextSelection, tintHex: null } : part
      )
      updateLayer(currentLayer)
    } else {
      addEyeLayer()
    }
  }

  const decrementEyeColor = () => {
    const eyeIndex = layerArr.findIndex(
      (layer) => layer.assetName === 'Etc_-_Eye_Color'
    )
    if (eyeIndex > -1) {
      const currentLayer = {
        ...layerArr[eyeIndex],
        parts: layerArr[eyeIndex].parts.map((part) => ({ ...part })),
      }
      const currentSelection = currentLayer.parts?.[0]?.selection
      const currentColorIndex = eyeColorOptions.findIndex(
        (color) => color === currentSelection
      )
      const nextSelection =
        currentColorIndex <= 0
          ? eyeColorOptions[eyeColorOptions.length - 1]
          : eyeColorOptions[currentColorIndex - 1]
      currentLayer.parts = currentLayer.parts.map((part, index) =>
        index === 0 ? { ...part, selection: nextSelection, tintHex: null } : part
      )
      updateLayer(currentLayer)
    } else {
      addEyeLayer()
    }
  }

  useEffect(() => {
    const eyeLayer = layerArr.find((layer) => layer.assetName === 'Etc_-_Eye_Color')
    const eyeSelection = eyeLayer?.parts?.[0]?.selection
    setHex(
      colors.find((colorObj) => colorObj.fileName === eyeSelection)?.hex || '#393939'
    )
  }, [layerArr])

  return (
    <EyesContainer>
      <TextContainer className='font-face-gm'>Eyes</TextContainer>
      <ButtonContainer onClick={() => decrementEyeColor()}>
        <InnerContainer>
          <LeftArrow />
        </InnerContainer>
      </ButtonContainer>
      <PreviewContainer>
        <DarkBorder>
          <ColorPreview hex={hex} />
        </DarkBorder>
      </PreviewContainer>
      <ButtonContainer onClick={() => incrementEyeColor()}>
        <InnerContainer>
          <RightArrow />
        </InnerContainer>
      </ButtonContainer>
    </EyesContainer>
  )
}

export default Eyes
