import React, { useState } from 'react'
import { StyledColorContainer, ColorImage } from './individual-color.style'
import useLayerStore from '../../../utils/store'
import colors from '../../../utils/colors'
import BorderContainer from '../../border-container/border-container'
import Tooltip from '@mui/material/Tooltip'

const IndividualColor = ({ color, primary, selection, partKey, layerId }) => {
  const layerArr = useLayerStore((state) => state.layerArr)
  const selectedLayer = useLayerStore((state) => state.selectedLayer)
  const setSelectedLayer = useLayerStore((state) => state.setSelectedLayer)
  const setColor = useLayerStore((state) => state.setColor)
  const setSecondary = useLayerStore((state) => state.setSecondary)
  const setPartSelection = useLayerStore((state) => state.setPartSelection)
  const [background, setBackground] = useState('white')
  const activeLayer = layerArr.find((layer) => layer.id === (layerId ?? selectedLayer))
  const resolvedPartKey =
    partKey || (primary ? activeLayer?.parts?.[0]?.key : activeLayer?.parts?.[1]?.key)
  const colorObject = colors.find((colorObject) => colorObject.fileName === color)
  const hex = colorObject?.hex || '#ffffff'

  const onClickColor = () => {
    if (layerId !== undefined && layerId !== null) {
      setSelectedLayer(layerId)
    }

    if (resolvedPartKey) {
      setPartSelection(resolvedPartKey, color)
      return
    }

    if (primary) {
      setColor(color)
    } else {
      setSecondary(color)
    }
  }

  return (
    <StyledColorContainer
      onClick={() => onClickColor()}
      onMouseEnter={() => setBackground('#bccccc')}
      onMouseLeave={() => setBackground('white')}
    >
      <BorderContainer outer={color === selection ? '#c45508' : false} inner={background}>
        <Tooltip title={colorObject?.name || color} arrow>
          <div>
            <ColorImage hex={hex} />
          </div>
        </Tooltip>
      </BorderContainer>
    </StyledColorContainer>
  )
}

export default IndividualColor
