import data, {
  bodyPartDefinitions,
  defaultSkinSelection,
  getAssetMeta,
  mapSelectionToPrefix,
} from './dataV2.js'

const getRandomOption = (options, fallbackSelection) => {
  const selectableOptions = options.filter((option) => !option.endsWith('None.png'))

  if (selectableOptions.length === 0) {
    return fallbackSelection
  }

  return selectableOptions[Math.floor(Math.random() * selectableOptions.length)]
}

const getBodyLinkedSelection = (partMeta, baseBodyColor) => {
  const mappedSelection = mapSelectionToPrefix(
    baseBodyColor || defaultSkinSelection,
    partMeta.prefix || 'primary'
  )

  if (partMeta.colorOptions.includes(mappedSelection)) {
    return mappedSelection
  }

  return partMeta.defaultSelection
}

const createPartState = (partMeta, selection, existingPart = null) => ({
  key: partMeta.key,
  label: partMeta.label,
  selection,
  tintHex: existingPart?.tintHex ?? null,
  hueShift: existingPart?.hueShift ?? 0,
  saturation: existingPart?.saturation ?? 0,
  lightness: existingPart?.lightness ?? 0,
})

const buildLayerFromAsset = (
  layerType,
  assetName,
  { randomizeColors = true, baseBodyColor = null, existingParts = [] } = {}
) => {
  const assetMeta = getAssetMeta(layerType, assetName)

  if (!assetMeta) {
    return null
  }

  const parts = assetMeta.layers.map((partMeta, index) => {
    const existingPart =
      existingParts.find((part) => part.key === partMeta.key) || existingParts[index] || null

    let selection = existingPart?.selection || null

    if (!partMeta.colorOptions.includes(selection)) {
      if (partMeta.isBodyLinked) {
        selection = getBodyLinkedSelection(partMeta, baseBodyColor)
      } else if (randomizeColors) {
        selection = getRandomOption(partMeta.colorOptions, partMeta.defaultSelection)
      } else {
        selection = partMeta.defaultSelection
      }
    }

    return createPartState(partMeta, selection, existingPart)
  })

  return {
    layerType,
    assetName,
    parts,
    isLocked: false,
    display: true,
    isBaseLayer: layerType === 'Body',
  }
}

const createBodyBaseLayers = (baseBodyColor = defaultSkinSelection) =>
  bodyPartDefinitions.map((bodyPart) => {
    const layer = buildLayerFromAsset('Body', bodyPart.assetName, {
      randomizeColors: false,
      baseBodyColor,
      existingParts: [{ key: 'body', selection: baseBodyColor }],
    })

    return {
      ...layer,
      isBaseLayer: true,
      isLocked: false,
      display: true,
    }
  })

const RandomizerTool = (itemType, options = {}) => {
  const assets = Object.keys(data[itemType] || {})

  if (assets.length === 0) {
    return {
      asset: null,
      parts: [],
      color: null,
      secondary: false,
    }
  }

  const randomAsset = assets[Math.floor(Math.random() * assets.length)]
  const layer = buildLayerFromAsset(itemType, randomAsset, {
    randomizeColors: true,
    baseBodyColor: options.baseBodyColor || null,
  })

  return {
    asset: randomAsset,
    parts: layer?.parts || [],
    color: layer?.parts?.[0]?.selection || null,
    secondary: layer?.parts?.[1]?.selection || false,
  }
}

export { buildLayerFromAsset, createBodyBaseLayers }

export default RandomizerTool
