import React, { useState } from 'react'
import { StyledAssetContainer, AssetImage } from './item-select-modal/individual-asset.style'
import useLayerStore from '../../utils/store'
import BorderContainer from '../border-container/border-container'
import Tooltip from '@mui/material/Tooltip'
import { getAssetPreviewPath } from '../../utils/dataV2'

const SearchAsset = ({ asset, layerType }) => {
  const addAssetLayer = useLayerStore((state) => state.addAssetLayer)
  const setSelectedLayer = useLayerStore((state) => state.setSelectedLayer)
  const [background, setBackground] = useState('white')
  const title = asset.replaceAll('_', ' ')
  const image = getAssetPreviewPath(layerType, asset)

  const onClickAsset = () => {
    const newLayerIndex = addAssetLayer(layerType, asset, true)
    if (newLayerIndex !== null) {
      setSelectedLayer(newLayerIndex)
    }
  }

  return (
    <StyledAssetContainer
      onClick={() => onClickAsset()}
      onMouseEnter={() => setBackground('#bccccc')}
      onMouseLeave={() => setBackground('white')}
    >
      <BorderContainer outer={false} inner={background}>
        <Tooltip title={title} arrow>
          <div>
            <AssetImage importedImage={image} />
          </div>
        </Tooltip>
      </BorderContainer>
    </StyledAssetContainer>
  )
}

export default SearchAsset
