import React from 'react'
import useOptionsStore from './utils/options-store'
import useLayerStore from '../../utils/store'
import BorderContainer from '../border-container/border-container'
import Tooltip from '@mui/material/Tooltip'
import {
  OptionsContainer,
  StyledOptionsContainer,
  Face,
  Hair,
  HeadGear,
  BackHand,
  UpperBody,
  ForeHand,
  Robe,
  LowerBody,
  Back,
  Accessories,
  Feet,
  Body,
  StyledGridItem,
  StyledButtonContainer,
} from './options.style'
import Grid from '@mui/material/Grid'

const Options = () => {
  const addRandomLayer = useLayerStore((state) => state.addRandomLayer)
  const addAssetLayer = useLayerStore((state) => state.addAssetLayer)
  const layerArr = useLayerStore((state) => state.layerArr)
  const setOptionsState = useOptionsStore((state) => state.setOptionsState)
  const setSelectedLayer = useLayerStore((state) => state.setSelectedLayer)

  const updateLayers = (layerType) => {
    const newLayerIndex = addRandomLayer(layerType)
    if (newLayerIndex !== null) {
      setSelectedLayer(newLayerIndex)
      setOptionsState('item')
    }
  }

  const openBodyEditor = () => {
    const bodyLayerIndex = layerArr.findIndex(
      (layer) => layer.layerType === 'Body' && layer.isBaseLayer
    )

    if (bodyLayerIndex > -1) {
      setSelectedLayer(bodyLayerIndex)
      setOptionsState('item')
    }
  }

  const addWeapon = () => {
    const backHandLayerIndex = addRandomLayer('Back_Hand')
    addAssetLayer('Sleeve', 'Short_Sleeve', true)

    if (backHandLayerIndex !== null) {
      setSelectedLayer(backHandLayerIndex)
      setOptionsState('item')
    }
  }

  return (
    <OptionsContainer>
      <BorderContainer>
        <StyledOptionsContainer container spacing={2} alignItems='flex-start'>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Face' arrow>
                <StyledButtonContainer>
                  <Face onClick={() => updateLayers('Face')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Hair' arrow>
                <StyledButtonContainer>
                  <Hair onClick={() => updateLayers('Hair')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Headgear' arrow>
                <StyledButtonContainer>
                  <HeadGear onClick={() => updateLayers('Headgear')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Accessories' arrow>
                <StyledButtonContainer>
                  <Accessories onClick={() => updateLayers('Accessories')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Upper Body' arrow>
                <StyledButtonContainer>
                  <UpperBody onClick={() => updateLayers('Upper_Body')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Robe' arrow>
                <StyledButtonContainer>
                  <Robe onClick={() => updateLayers('Robe')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Back' arrow>
                <StyledButtonContainer>
                  <Back onClick={() => updateLayers('Back')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Body' arrow>
                <StyledButtonContainer>
                  <Body onClick={() => openBodyEditor()} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Lower Body' arrow>
                <StyledButtonContainer>
                  <LowerBody onClick={() => updateLayers('Lower_Body')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Backhand' arrow>
                <StyledButtonContainer>
                  <BackHand onClick={() => addWeapon()} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Forehand' arrow>
                <StyledButtonContainer>
                  <ForeHand onClick={() => updateLayers('Forehand')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
          <Grid item xs={4} sm={4} md={3}>
            <StyledGridItem>
              <Tooltip title='Feet' arrow>
                <StyledButtonContainer>
                  <Feet onClick={() => updateLayers('Feet')} />
                </StyledButtonContainer>
              </Tooltip>
            </StyledGridItem>
          </Grid>
        </StyledOptionsContainer>
      </BorderContainer>
    </OptionsContainer>
  )
}

export default Options
