import React, { useEffect, useMemo, useState } from 'react'
import Modal from '@mui/material/Modal'
import {
  StyledContainer,
  InnerModal,
} from '../item-select-modal/item-select-modal.style'
import IndividualColor from './individual-color'
import BorderContainer from '../../border-container/border-container'
import {
  CloseRow,
  CloseButton,
} from '../item-select-modal/item-select-modal.style'
import useLayerStore from '../../../utils/store'
import colors from '../../../utils/colors'
import {
  getAssetImagePath,
  getAssetPartMeta,
  getNeutralAssetImagePath,
  isEmptyColorSelection,
} from '../../../utils/dataV2'
import { clampValue, processImageColor } from '../../../utils/color-processing'
import {
  TintUtilityContainer,
  TintModeRow,
  TintModeSelect,
  TintTopRow,
  TintBottomRow,
  TintPreviewRow,
  TintLabel,
  TintPreview,
  TintInput,
  TintButton,
  SliderRow,
  SliderLabel,
  SliderInput,
  SliderNumber,
  LivePreviewBox,
  LivePreviewImage,
  ModalSectionTitle,
} from './color-select-modal.style'

const parseNumericInput = (value, fallback = 0) => {
  const parsedValue = Number(value)
  return Number.isFinite(parsedValue) ? parsedValue : fallback
}

const ColorSelectModal = ({
  open,
  onClose,
  options,
  primary,
  selection,
  partKey,
  layerId,
}) => {
  const layerArr = useLayerStore((state) => state.layerArr)
  const selectedLayer = useLayerStore((state) => state.selectedLayer)
  const setSelectedLayer = useLayerStore((state) => state.setSelectedLayer)
  const setPartTintHex = useLayerStore((state) => state.setPartTintHex)
  const setPartColorAdjustments = useLayerStore(
    (state) => state.setPartColorAdjustments
  )
  const [customTintHex, setCustomTintHex] = useState('#ffffff')
  const [hueShift, setHueShift] = useState(0)
  const [saturation, setSaturation] = useState(0)
  const [lightness, setLightness] = useState(0)
  const [livePreviewImage, setLivePreviewImage] = useState('')

  const activeLayerId = layerId ?? selectedLayer
  const selectedLayerData = layerArr.find((layer) => layer.id === activeLayerId)
  const resolvedPartKey =
    partKey ||
    (primary ? selectedLayerData?.parts?.[0]?.key : selectedLayerData?.parts?.[1]?.key)
  const selectedPart = selectedLayerData?.parts?.find(
    (part) => part.key === resolvedPartKey
  )
  const currentTintHex = selectedPart?.tintHex || null
  const currentHueShift = selectedPart?.hueShift || 0
  const currentSaturation = selectedPart?.saturation || 0
  const currentLightness = selectedPart?.lightness || 0

  const selectedColorHex = useMemo(() => {
    const colorObject = colors.find((colorObject) => colorObject.fileName === selection)
    return colorObject?.hex || '#ffffff'
  }, [selection])

  useEffect(() => {
    if (open) {
      setCustomTintHex(currentTintHex || selectedColorHex)
      setHueShift(currentHueShift)
      setSaturation(currentSaturation)
      setLightness(currentLightness)
    } else {
      setLivePreviewImage('')
    }
  }, [
    open,
    currentTintHex,
    selectedColorHex,
    currentHueShift,
    currentSaturation,
    currentLightness,
  ])

  useEffect(() => {
    let isCurrent = true

    const renderLivePreview = async () => {
      if (
        !open ||
        !selectedLayerData ||
        !resolvedPartKey ||
        !selection ||
        isEmptyColorSelection(selection)
      ) {
        if (isCurrent) {
          setLivePreviewImage('')
        }
        return
      }

      const partMeta = getAssetPartMeta(
        selectedLayerData.layerType,
        selectedLayerData.assetName,
        resolvedPartKey
      )

      if (!partMeta) {
        if (isCurrent) {
          setLivePreviewImage('')
        }
        return
      }

      const sourceImage = getAssetImagePath(
        selectedLayerData.layerType,
        selectedLayerData.assetName,
        resolvedPartKey,
        selection
      )

      if (!sourceImage) {
        if (isCurrent) {
          setLivePreviewImage('')
        }
        return
      }

      const neutralImage = getNeutralAssetImagePath(
        selectedLayerData.layerType,
        selectedLayerData.assetName,
        resolvedPartKey
      )

      const normalizedSelected = (selectedColorHex || '').toLowerCase()
      const normalizedTint = (customTintHex || '').toLowerCase()
      const hasCustomTint = normalizedSelected !== normalizedTint

      const previewBaseImage =
        partMeta.type === 'legacy' ? neutralImage || sourceImage : sourceImage
      const previewTintHex =
        partMeta.type === 'legacy'
          ? neutralImage
            ? customTintHex || selectedColorHex
            : hasCustomTint
              ? customTintHex
              : null
          : customTintHex || selectedColorHex

      const processedPreview = await processImageColor(
        previewBaseImage,
        previewTintHex,
        {
          hueShift,
          saturation,
          lightness,
        },
        {
          tintMode: partMeta.type === 'tint' ? 'luminance-map' : 'multiply',
        }
      )

      if (isCurrent) {
        setLivePreviewImage(processedPreview)
      }
    }

    renderLivePreview()

    return () => {
      isCurrent = false
    }
  }, [
    open,
    selectedLayerData,
    resolvedPartKey,
    selection,
    selectedColorHex,
    customTintHex,
    hueShift,
    saturation,
    lightness,
  ])

  const applyColorTool = () => {
    if (!resolvedPartKey) {
      return
    }

    const normalizedSelected = (selectedColorHex || '').toLowerCase()
    const normalizedTint = (customTintHex || '').toLowerCase()
    const tintValue = normalizedTint === normalizedSelected ? null : customTintHex

    setSelectedLayer(activeLayerId)
    setPartTintHex(resolvedPartKey, tintValue)
    setPartColorAdjustments(resolvedPartKey, {
      hueShift: clampValue(hueShift, -180, 180),
      saturation: clampValue(saturation, -100, 100),
      lightness: clampValue(lightness, -100, 100),
    })
  }

  const resetColorTool = () => {
    if (!resolvedPartKey) {
      return
    }

    setSelectedLayer(activeLayerId)
    setPartTintHex(resolvedPartKey, null)
    setPartColorAdjustments(resolvedPartKey, {
      hueShift: 0,
      saturation: 0,
      lightness: 0,
    })
    setCustomTintHex(selectedColorHex)
    setHueShift(0)
    setSaturation(0)
    setLightness(0)
  }

  return (
    <Modal open={open} onClose={onClose} hideBackdrop disableAutoFocus>
      <StyledContainer>
        <BorderContainer>
          <InnerModal>
            <CloseRow>
              <CloseButton onClick={onClose} />
            </CloseRow>
            <TintUtilityContainer>
              <TintModeRow>
                <TintModeSelect value={resolvedPartKey || 'selected'} disabled>
                  <option value={resolvedPartKey || 'selected'}>
                    {selectedPart?.label || 'Selected Part'}
                  </option>
                </TintModeSelect>
              </TintModeRow>
              <TintTopRow>
                <TintLabel>Tint Override</TintLabel>
                <TintPreview color={customTintHex || '#ffffff'} />
                <TintInput
                  type='color'
                  value={customTintHex || '#ffffff'}
                  onChange={(event) => setCustomTintHex(event.target.value)}
                />
              </TintTopRow>
              <TintPreviewRow>
                <TintLabel>Live Preview</TintLabel>
                <LivePreviewBox>
                  <BorderContainer inner='white'>
                    <LivePreviewImage importedImage={livePreviewImage} />
                  </BorderContainer>
                </LivePreviewBox>
              </TintPreviewRow>
              <SliderRow>
                <SliderLabel>Hue:</SliderLabel>
                <SliderInput
                  type='range'
                  min={-180}
                  max={180}
                  value={hueShift}
                  onChange={(event) =>
                    setHueShift(
                      clampValue(parseNumericInput(event.target.value), -180, 180)
                    )
                  }
                />
                <SliderNumber
                  type='number'
                  min={-180}
                  max={180}
                  value={hueShift}
                  onChange={(event) =>
                    setHueShift(
                      clampValue(parseNumericInput(event.target.value), -180, 180)
                    )
                  }
                />
              </SliderRow>
              <SliderRow>
                <SliderLabel>Saturation:</SliderLabel>
                <SliderInput
                  type='range'
                  min={-100}
                  max={100}
                  value={saturation}
                  onChange={(event) =>
                    setSaturation(
                      clampValue(parseNumericInput(event.target.value), -100, 100)
                    )
                  }
                />
                <SliderNumber
                  type='number'
                  min={-100}
                  max={100}
                  value={saturation}
                  onChange={(event) =>
                    setSaturation(
                      clampValue(parseNumericInput(event.target.value), -100, 100)
                    )
                  }
                />
              </SliderRow>
              <SliderRow>
                <SliderLabel>Lightness:</SliderLabel>
                <SliderInput
                  type='range'
                  min={-100}
                  max={100}
                  value={lightness}
                  onChange={(event) =>
                    setLightness(
                      clampValue(parseNumericInput(event.target.value), -100, 100)
                    )
                  }
                />
                <SliderNumber
                  type='number'
                  min={-100}
                  max={100}
                  value={lightness}
                  onChange={(event) =>
                    setLightness(
                      clampValue(parseNumericInput(event.target.value), -100, 100)
                    )
                  }
                />
              </SliderRow>
              <TintBottomRow>
                <TintButton onClick={() => applyColorTool()}>Apply Tool</TintButton>
                <TintButton onClick={() => resetColorTool()}>Reset Tool</TintButton>
              </TintBottomRow>
            </TintUtilityContainer>
            <ModalSectionTitle>Preset Colors</ModalSectionTitle>
            {(options || []).map((colorOption, index) => (
              <IndividualColor
                key={'color#' + index}
                color={colorOption}
                selection={selection}
                partKey={resolvedPartKey}
                layerId={activeLayerId}
              />
            ))}
          </InnerModal>
        </BorderContainer>
      </StyledContainer>
    </Modal>
  )
}

export default ColorSelectModal
